//! Source preserving timeline editing with bounded snapshot history.
mod ops;

use crate::{decode, AssetRef, DecodeFailure, Error, LoopMode, TimelineContext, MAX_SOURCE_BYTES};
use std::sync::Arc;

pub const DEFAULT_HISTORY_COMMANDS: usize = 16;
pub const DEFAULT_HISTORY_BYTES: usize = 128 * 1024 * 1024;
pub const MAX_HISTORY_COMMANDS: usize = 1024;
pub const MAX_HISTORY_BYTES: usize = 512 * 1024 * 1024;
const VALUE_JSON_LIMIT: usize = 512;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EditLimits { pub commands: usize, pub bytes: usize }
impl Default for EditLimits {
    fn default() -> Self { Self { commands: DEFAULT_HISTORY_COMMANDS, bytes: DEFAULT_HISTORY_BYTES } }
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EditFailure { pub error: Error, pub offset: usize }
impl From<DecodeFailure> for EditFailure {
    fn from(value: DecodeFailure) -> Self { Self { error: value.error, offset: value.offset } }
}
pub type EditResult<T = ()> = Result<T, EditFailure>;

/// Owns source snapshots. Editor methods require exclusive access; cloned leases
/// are immutable, `Send + Sync`, and remain valid after history eviction/drop.
pub struct TimelineEdit {
    snapshots: Vec<Arc<Vec<u8>>>,
    cursor: usize,
    command_limit: usize,
    byte_limit: usize,
}
#[derive(Clone)]
pub struct TimelineSourceLease(Arc<Vec<u8>>);
impl TimelineSourceLease { pub fn bytes(&self) -> &[u8] { self.0.as_slice() } }

impl TimelineEdit {
    pub fn new(source: &[u8], context: &TimelineContext, limits: EditLimits) -> EditResult<Self> {
        if limits.commands == 0 || limits.commands > MAX_HISTORY_COMMANDS || limits.bytes == 0 || limits.bytes > MAX_HISTORY_BYTES {
            return Err(fail(Error::InvalidArgument, 0));
        }
        decode(source, context).map_err(EditFailure::from)?;
        if source.is_empty() || source.len() > limits.bytes { return Err(fail(Error::Limit, 0)); }
        let mut owned = Vec::new(); owned.try_reserve_exact(source.len()).map_err(|_| fail(Error::Limit, 0))?;
        owned.extend_from_slice(source);
        let mut snapshots = Vec::new(); snapshots.try_reserve_exact(limits.commands.checked_add(1).ok_or_else(|| fail(Error::Limit,0))?).map_err(|_|fail(Error::Limit,0))?;
        // Arc's allocation is provided by std and cannot report allocation failure.
        snapshots.push(Arc::new(owned));
        Ok(Self { snapshots, cursor: 0, command_limit: limits.commands, byte_limit: limits.bytes })
    }
    pub fn source(&self) -> &[u8] { self.snapshots[self.cursor].as_slice() }
    pub fn source_lease(&self) -> TimelineSourceLease { TimelineSourceLease(self.snapshots[self.cursor].clone()) }
    pub fn undo_count(&self) -> usize { self.cursor }
    pub fn redo_count(&self) -> usize { self.snapshots.len().saturating_sub(self.cursor + 1) }

    pub fn undo(&mut self, context: &TimelineContext) -> EditResult {
        if self.cursor == 0 { return Err(fail(Error::InvalidValue, 0)); }
        let next = self.cursor - 1;
        decode(&self.snapshots[next], context).map_err(EditFailure::from)?;
        self.cursor = next; Ok(())
    }
    pub fn redo(&mut self, context: &TimelineContext) -> EditResult {
        let next = self.cursor.checked_add(1).ok_or_else(|| fail(Error::Limit, 0))?;
        let bytes = self.snapshots.get(next).ok_or_else(|| fail(Error::InvalidValue, 0))?;
        decode(bytes, context).map_err(EditFailure::from)?;
        self.cursor = next; Ok(())
    }
    pub(super) fn commit(&mut self, context: &TimelineContext, candidate: Vec<u8>) -> EditResult {
        if candidate.as_slice() == self.source() { return Ok(()); }
        if candidate.len() > MAX_SOURCE_BYTES || candidate.len() > self.byte_limit { return Err(fail(Error::Limit, 0)); }
        decode(&candidate, context).map_err(EditFailure::from)?;
        let mut retained = self.cursor + 1;
        let mut removed = 0usize;
        let mut retained_bytes = 0usize;
        for bytes in &self.snapshots[..retained] { retained_bytes = retained_bytes.checked_add(bytes.len()).ok_or_else(||fail(Error::Limit,0))?; }
        while retained + 1 > self.command_limit + 1 || retained_bytes > self.byte_limit - candidate.len() {
            if retained <= 1 { return Err(fail(Error::Limit, 0)); }
            retained_bytes -= self.snapshots[removed].len(); removed += 1; retained -= 1;
        }
        // Arc allocates its reference-count header through std (not fallibly).
        // The already validated Vec buffer itself is moved without another copy.
        let next = Arc::new(candidate);
        self.snapshots.truncate(self.cursor + 1);
        if removed != 0 { self.snapshots.drain(..removed); self.cursor -= removed; }
        self.snapshots.push(next);
        self.cursor = self.snapshots.len() - 1;
        Ok(())
    }

    pub fn add_drawing_track(&mut self, context:&TimelineContext, track_id:&[u8], target_id:&[u8], asset_name:&[u8], track_name:&[u8])->EditResult { ops::add_drawing_track(self,context,track_id,target_id,asset_name,track_name) }
    pub fn add_property_track(&mut self, context:&TimelineContext, track_id:&[u8], target_id:&[u8], property:&[u8], value_type:&[u8], interpolation:&[u8], value_json:&[u8], track_name:&[u8])->EditResult { ops::add_property_track(self,context,track_id,target_id,property,value_type,interpolation,value_json,track_name) }
    pub fn add_property_track_key(&mut self, context:&TimelineContext, track_id:&[u8], target_id:&[u8], property:&[u8], value_type:&[u8], interpolation:&[u8], initial_json:&[u8], tick:u32, value_json:&[u8], track_name:&[u8])->EditResult { ops::add_property_track_key(self,context,track_id,target_id,property,value_type,interpolation,initial_json,tick,value_json,track_name) }
    pub fn set_property_key(&mut self, context:&TimelineContext, track_id:&[u8], tick:u32, value_json:&[u8])->EditResult { ops::set_property_key(self,context,track_id,tick,value_json) }
    pub fn set_cel(&mut self, context:&TimelineContext, track_id:&[u8], tick:u32, asset_name:&[u8], label:&[u8])->EditResult { ops::set_cel(self,context,track_id,tick,asset_name,label) }
    pub fn remove_cel(&mut self, context:&TimelineContext, track_id:&[u8], tick:u32)->EditResult { ops::remove_cel(self,context,track_id,tick) }
    pub fn move_item(&mut self, context:&TimelineContext, track_id:&[u8], from_tick:u32, to_tick:u32)->EditResult { ops::move_item(self,context,track_id,from_tick,to_tick) }
    pub fn set_loop(&mut self, context:&TimelineContext, mode:LoopMode)->EditResult { ops::set_loop(self,context,mode) }
    pub fn set_onion(&mut self, context:&TimelineContext, before:u32, after:u32, opacity:f64)->EditResult { ops::set_onion(self,context,before,after,opacity) }
}

pub(super) fn fail(error:Error,offset:usize)->EditFailure { EditFailure{error,offset} }
pub(super) fn validate_utf8(value:&[u8])->bool { std::str::from_utf8(value).is_ok() }
pub(super) fn valid_id(value:&[u8])->bool { !value.is_empty()&&value.len()<=128&&value.iter().all(|b|b.is_ascii_alphanumeric()||matches!(*b,b'_'|b'-')) }
pub(super) fn valid_target(context:&TimelineContext,id:&[u8])->bool { context.scene_ids.binary_search_by(|candidate|candidate.as_slice().cmp(id)).is_ok() }
pub(super) fn valid_asset(context:&TimelineContext,name:&[u8])->bool { context.assets.iter().any(|a: &AssetRef|a.name==name&&a.media_type==b"image/svg+xml") }

use super::{fail, valid_asset, valid_id, valid_target, validate_utf8, EditFailure, EditResult, TimelineEdit, VALUE_JSON_LIMIT};
use crate::json::{array_spans, decode_string, object_fields, Field};
use crate::schema::{field, string, uint};
use crate::{decode, Error, LoopMode, TimelineContext, MAX_ITEMS, MAX_ITEMS_PER_TRACK, MAX_SOURCE_BYTES, MAX_TRACKS};
use vexel_base::Span;

struct Track { items: Span, item_spans: Vec<Span>, drawing: bool, duration: u32 }
fn at(error:Error,offset:usize)->EditFailure{fail(error,offset)}
fn fields(source:&[u8],span:Span)->Result<Vec<Field>,EditFailure>{object_fields(source,span,None).map_err(Into::into)}
fn root_span(source:&[u8])->Result<Span,EditFailure>{let mut r=crate::json::Reader::new(source,None);r.scan(0).map_err(EditFailure::from)?;Ok(Span{start:0,end:r.cursor})}
fn selected(source:&[u8],context:&TimelineContext,id:&[u8])->Result<(Track,usize),EditFailure>{
    let view=decode(source,context).map_err(EditFailure::from)?;
    let root_fields=fields(source,root_span(source)?)?;
    let tracks=field(&root_fields,b"tracks").ok_or_else(||at(Error::InvalidSchema,0))?.value;
    let track_spans=array_spans(source,tracks,MAX_TRACKS,None).map_err(EditFailure::from)?;
    let mut found=None;
    for (index,span) in track_spans.iter().enumerate(){
        let f=fields(source,*span)?;
        if string(source,field(&f,b"id").ok_or_else(||at(Error::InvalidSchema,span.start))?.value).map_err(EditFailure::from)?.as_slice()==id { found=Some((index,*span,f));break; }
    }
    let (index,span,f)=found.ok_or_else(||at(Error::InvalidReference,0))?;
    let drawing=string(source,field(&f,b"kind").ok_or_else(||at(Error::InvalidSchema,span.start))?.value).map_err(EditFailure::from)?==b"drawing";
    let item_field=field(&f,if drawing{b"cels"}else{b"keys"}).ok_or_else(||at(Error::InvalidSchema,span.start))?;
    let item_spans=array_spans(source,item_field.value,MAX_ITEMS_PER_TRACK,None).map_err(EditFailure::from)?;
    Ok((Track{items:item_field.value,item_spans,drawing,duration:view.duration_ticks()},index))
}
fn splice(source:&[u8],start:usize,remove:usize,insert:&[u8])->EditResult<Vec<u8>>{
    if start>source.len()||remove>source.len()-start{return Err(at(Error::InvalidSchema,start));}
    let len=source.len().checked_sub(remove).and_then(|n|n.checked_add(insert.len())).ok_or_else(||at(Error::Limit,start))?;
    if len>MAX_SOURCE_BYTES{return Err(at(Error::Limit,start));}
    let mut out=Vec::new();out.try_reserve_exact(len).map_err(|_|at(Error::Limit,start))?;
    out.extend_from_slice(&source[..start]);out.extend_from_slice(insert);out.extend_from_slice(&source[start+remove..]);Ok(out)
}
fn append(out:&mut Vec<u8>,part:&[u8])->EditResult{out.try_reserve(part.len()).map_err(|_|at(Error::Limit,0))?;out.extend_from_slice(part);Ok(())}
fn json_string(raw:&[u8])->EditResult<Vec<u8>>{
    if !validate_utf8(raw)||raw.len()>crate::MAX_STRING_BYTES{return Err(at(Error::InvalidArgument,0));}
    let cap=raw.len().checked_mul(6).and_then(|n|n.checked_add(2)).ok_or_else(||at(Error::Limit,0))?;
    let mut out=Vec::new();out.try_reserve_exact(cap).map_err(|_|at(Error::Limit,0))?;out.push(b'"');
    const HEX:&[u8]=b"0123456789abcdef";
    for &b in raw{match b{b'"'|b'\\'=>{out.push(b'\\');out.push(b)},0..=31=>{out.extend_from_slice(b"\\u00");out.push(HEX[(b>>4)as usize]);out.push(HEX[(b&15)as usize]);},_=>out.push(b)}}out.push(b'"');Ok(out)
}
fn value_json(raw:&[u8])->Result<(),EditFailure>{
    if raw.is_empty(){return Err(at(Error::InvalidArgument,0));}if raw.len()>VALUE_JSON_LIMIT{return Err(at(Error::Limit,0));}
    // Syntax and typed-value errors are reported after splicing, with offsets
    // in the candidate document as in the C contract.
    Ok(())
}
fn track_candidate(edit:&TimelineEdit,context:&TimelineContext,id:&[u8],payload:&[u8],target:Option<&[u8]>)->EditResult<Vec<u8>>{
    let source=edit.source();let view=decode(source,context).map_err(EditFailure::from)?;
    if view.track_count()>=MAX_TRACKS{return Err(at(Error::Limit,view.tracks_span().start));}
    if !valid_id(id){return Err(at(Error::InvalidArgument,0));}
    for i in 0..view.track_count(){let t=view.track_at(i).ok_or_else(||at(Error::InvalidSchema,0))?;
        let decoded=decode_string(t.id).ok_or_else(||at(Error::Limit,0))?;if decoded==id{return Err(at(Error::Duplicate,view.tracks_span().start));}}
    if target.is_some_and(|target|!valid_target(context,target)){return Err(at(Error::InvalidReference,0));}
    let tracks= view.tracks_span();let spans=array_spans(source,tracks,MAX_TRACKS,None).map_err(EditFailure::from)?;
    let insert_at=spans.last().map(|s|s.end).unwrap_or(tracks.end-1);let comma=if spans.is_empty(){&b""[..]}else{&b","[..]};
    let insertion_len=comma.len().checked_add(payload.len()).ok_or_else(||at(Error::Limit,insert_at))?;
    let mut insertion=Vec::new();insertion.try_reserve_exact(insertion_len).map_err(|_|at(Error::Limit,insert_at))?;insertion.extend_from_slice(comma);insertion.extend_from_slice(payload);
    splice(source,insert_at,0,&insertion)
}
fn track_json_add(edit:&mut TimelineEdit,context:&TimelineContext,id:&[u8],payload:&[u8])->EditResult{
    let candidate=track_candidate(edit,context,id,payload,None)?;edit.commit(context,candidate)
}
fn make_drawing(id:&[u8],target:&[u8],asset:&[u8],name:&[u8])->EditResult<Vec<u8>>{
    let (i,t,a,n)=(json_string(id)?,json_string(target)?,json_string(asset)?,json_string(name)?);
    let mut out=Vec::new();out.try_reserve(i.len()+t.len()+a.len()+n.len()+96).map_err(|_|at(Error::Limit,0))?;
    out.extend_from_slice(b"{\"id\":");out.extend(i);out.extend_from_slice(b",\"kind\":\"drawing\",\"target\":");out.extend(t);out.extend_from_slice(b",\"visible\":true,\"cels\":[{\"tick\":0,\"asset\":");out.extend(a);out.extend_from_slice(b"}]");
    if !name.is_empty(){out.extend_from_slice(b",\"name\":");out.extend(n);}out.push(b'}');Ok(out)
}
pub(super) fn add_drawing_track(edit:&mut TimelineEdit,context:&TimelineContext,id:&[u8],target:&[u8],asset:&[u8],name:&[u8])->EditResult{
    if id.is_empty()||id.len()>128||!validate_utf8(name)||name.len()>crate::MAX_STRING_BYTES{return Err(at(Error::InvalidArgument,0));}
    if let Some(offset)=id.iter().position(|b|!b.is_ascii_alphanumeric()&&!matches!(*b,b'_'|b'-')){return Err(at(Error::InvalidValue,offset));}
    let _view=decode(edit.source(),context).map_err(EditFailure::from)?;
    if !valid_target(context,target)||!valid_asset(context,asset){return Err(at(Error::InvalidReference,0));}
    let payload=make_drawing(id,target,asset,name)?;track_json_add(edit,context,id,&payload)
}
fn make_property(id:&[u8],target:&[u8],property:&[u8],ty:&[u8],interp:&[u8],value:&[u8],extra:Option<(u32,&[u8])>,name:&[u8])->EditResult<Vec<u8>>{
    for s in [id,target,property,ty,interp,name]{if !validate_utf8(s)||s.len()>crate::MAX_STRING_BYTES{return Err(at(Error::InvalidArgument,0));}}
    value_json(value)?;if let Some((_,raw))=extra{value_json(raw)?;}let (i,t,p,y,n)=(json_string(id)?,json_string(target)?,json_string(property)?,json_string(ty)?,json_string(interp)?);
    let extra_len=extra.map_or(0,|(_,raw)|raw.len().saturating_add(40));
    let cap=i.len().checked_add(t.len()).and_then(|v|v.checked_add(p.len())).and_then(|v|v.checked_add(y.len())).and_then(|v|v.checked_add(n.len())).and_then(|v|v.checked_add(value.len())).and_then(|v|v.checked_add(extra_len)).and_then(|v|v.checked_add(name.len().saturating_mul(6))).and_then(|v|v.checked_add(180)).ok_or_else(||at(Error::Limit,0))?;
    let mut out=Vec::new();out.try_reserve_exact(cap).map_err(|_|at(Error::Limit,0))?;
    out.extend_from_slice(b"{\"id\":");out.extend(i);out.extend_from_slice(b",\"kind\":\"property\",\"target\":");out.extend(t);out.extend_from_slice(b",\"visible\":true,\"property\":");out.extend(p);out.extend_from_slice(b",\"value_type\":");out.extend(y);out.extend_from_slice(b",\"interpolation\":");out.extend(n);out.extend_from_slice(b",\"keys\":[{\"tick\":0,\"value\":");out.extend_from_slice(value);out.push(b'}');
    if let Some((tick,raw))=extra{out.extend_from_slice(b",{\"tick\":");out.extend_from_slice(tick.to_string().as_bytes());out.extend_from_slice(b",\"value\":");out.extend_from_slice(raw);out.push(b'}');}out.push(b']');
    if !name.is_empty(){out.extend_from_slice(b",\"name\":");out.extend(json_string(name)?);}out.push(b'}');Ok(out)
}
pub(super) fn add_property_track(edit:&mut TimelineEdit,context:&TimelineContext,id:&[u8],target:&[u8],property:&[u8],ty:&[u8],interp:&[u8],value:&[u8],name:&[u8])->EditResult{
    if !valid_id(id)||target.is_empty()||target.len()>crate::MAX_STRING_BYTES{return Err(at(Error::InvalidArgument,0));}
    let payload=make_property(id,target,property,ty,interp,value,None,name)?;
    let candidate=track_candidate(edit,context,id,&payload,Some(target))?;edit.commit(context,candidate)
}
pub(super) fn add_property_track_key(edit:&mut TimelineEdit,context:&TimelineContext,id:&[u8],target:&[u8],property:&[u8],ty:&[u8],interp:&[u8],initial:&[u8],tick:u32,value:&[u8],name:&[u8])->EditResult{
    if tick==0{return Err(at(Error::InvalidArgument,0));}
    decode(edit.source(),context).map_err(EditFailure::from)?;
    if !valid_id(id)||target.is_empty()||target.len()>crate::MAX_STRING_BYTES{return Err(at(Error::InvalidArgument,0));}
    let initial_payload=make_property(id,target,property,ty,interp,initial,None,name)?;
    let initial_candidate=track_candidate(edit,context,id,&initial_payload,Some(target))?;
    let current=decode(edit.source(),context).map_err(EditFailure::from)?;
    decode(&initial_candidate,context).map_err(EditFailure::from)?;
    if tick>=current.duration_ticks(){return Err(at(Error::InvalidValue,0));}
    let payload=make_property(id,target,property,ty,interp,initial,Some((tick,value)),name)?;
    let candidate=track_candidate(edit,context,id,&payload,Some(target))?;edit.commit(context,candidate)
}
fn insert_item(source:&[u8],array:Span,spans:&[Span],index:Option<usize>,replace:bool,item:&[u8])->EditResult<Vec<u8>>{
    let (insert_at,remove,insert)=if let Some(i)=index{let len=item.len().checked_add(usize::from(!replace)).ok_or_else(||at(Error::Limit,spans[i].start))?;let mut b=Vec::new();b.try_reserve_exact(len).map_err(|_|at(Error::Limit,spans[i].start))?;b.extend_from_slice(item);if !replace{b.push(b',');}(spans[i].start,if replace{spans[i].end-spans[i].start}else{0},b)}else{
        let insert_at=spans.last().map(|s|s.end).unwrap_or(array.end-1);let len=item.len().checked_add(usize::from(!spans.is_empty())).ok_or_else(||at(Error::Limit,insert_at))?;let mut b=Vec::new();b.try_reserve_exact(len).map_err(|_|at(Error::Limit,insert_at))?;
        if !spans.is_empty(){b.push(b',');}b.extend_from_slice(item);(insert_at,0,b)
    };splice(source,insert_at,remove,&insert)
}
fn make_key(tick:u32,value:&[u8])->EditResult<Vec<u8>>{value_json(value)?;let mut out=Vec::new();out.try_reserve(value.len()+40).map_err(|_|at(Error::Limit,0))?;out.extend_from_slice(b"{\"tick\":");out.extend_from_slice(tick.to_string().as_bytes());out.extend_from_slice(b",\"value\":");out.extend_from_slice(value);out.push(b'}');Ok(out)}
fn make_cel(tick:u32,asset:&[u8],label:&[u8])->EditResult<Vec<u8>>{let (a,l)=(json_string(asset)?,json_string(label)?);let mut out=Vec::new();out.try_reserve(a.len()+l.len()+48).map_err(|_|at(Error::Limit,0))?;out.extend_from_slice(b"{\"tick\":");out.extend_from_slice(tick.to_string().as_bytes());out.extend_from_slice(b",\"asset\":");out.extend(a);if !label.is_empty(){out.extend_from_slice(b",\"label\":");out.extend(l);}out.push(b'}');Ok(out)}
fn change_item(edit:&mut TimelineEdit,context:&TimelineContext,id:&[u8],tick:u32,raw:&[u8],drawing:bool)->EditResult{
    let source=edit.source();let (track,_)=selected(source,context,id)?;if track.drawing!=drawing{return Err(at(Error::InvalidArgument,0));}if tick>=track.duration{return Err(at(Error::InvalidValue,0));}
    let mut replace=None;let mut insert=None;let mut total=0usize;
    let view=decode(source,context).map_err(EditFailure::from)?;for i in 0..view.track_count(){total=total.checked_add(view.track_at(i).ok_or_else(||at(Error::InvalidSchema,0))?.item_count).ok_or_else(||at(Error::Limit,0))?;}
    for (i,span) in track.item_spans.iter().enumerate(){let f=fields(source,*span)?;let atick=uint(source,field(&f,b"tick").ok_or_else(||at(Error::InvalidSchema,span.start))?.value).map_err(EditFailure::from)?;if atick==tick{replace=Some(i);break;}if atick>tick{insert=Some(i);break;}}
    if replace.is_none()&&(track.item_spans.len()>=MAX_ITEMS_PER_TRACK||total>=MAX_ITEMS){return Err(at(Error::Limit,track.items.start));}
    let candidate=insert_item(source,track.items,&track.item_spans,replace.or(insert),replace.is_some(),raw)?;edit.commit(context,candidate)
}
pub(super) fn set_property_key(edit:&mut TimelineEdit,context:&TimelineContext,id:&[u8],tick:u32,value:&[u8])->EditResult{
    if id.is_empty()||value.is_empty(){return Err(at(Error::InvalidArgument,0));}
    let (track,_)=selected(edit.source(),context,id)?;if track.drawing{return Err(at(Error::InvalidArgument,0));}
    if tick>=track.duration{return Err(at(Error::InvalidValue,0));}
    let key=make_key(tick,value)?;change_item(edit,context,id,tick,&key,false)
}
pub(super) fn set_cel(edit:&mut TimelineEdit,context:&TimelineContext,id:&[u8],tick:u32,asset:&[u8],label:&[u8])->EditResult{
    if !valid_asset(context,asset){return Err(at(Error::InvalidReference,0));}if !validate_utf8(label)||label.len()>crate::MAX_STRING_BYTES{return Err(at(Error::InvalidArgument,0));}change_item(edit,context,id,tick,&make_cel(tick,asset,label)?,true)
}
pub(super) fn remove_cel(edit:&mut TimelineEdit,context:&TimelineContext,id:&[u8],tick:u32)->EditResult{
    let source=edit.source();let (track,_)=selected(source,context,id)?;if !track.drawing{return Err(at(Error::InvalidArgument,0));}
    let idx=track.item_spans.iter().enumerate().find_map(|(i,s)|{let f=fields(source,*s).ok()?;let t=uint(source,field(&f,b"tick")?.value).ok()?;(t==tick).then_some(i)}).ok_or_else(||at(Error::InvalidReference,0))?;
    if track.item_spans.len()<=1{return Err(at(Error::InvalidValue,0));}
    let span=track.item_spans[idx];let (start,end)=if idx==0{(span.start,track.item_spans[1].start)}else{
        let mut comma=track.item_spans[idx-1].end;while comma<span.start&&source[comma]!=b','{comma+=1;}
        if comma==span.start{return Err(at(Error::InvalidSchema,span.start));}(comma,span.end)
    };
    let candidate=splice(source,start,end-start,&[])?;edit.commit(context,candidate)
}

pub(super) fn move_item(edit:&mut TimelineEdit,context:&TimelineContext,id:&[u8],from:u32,to:u32)->EditResult{
    if id.is_empty(){return Err(at(Error::InvalidArgument,0));}
    let source=edit.source();let (track,_)=selected(source,context,id)?;
    let index=track.item_spans.iter().enumerate().find_map(|(i,s)|{let f=fields(source,*s).ok()?;let t=uint(source,field(&f,b"tick")?.value).ok()?;(t==from).then_some(i)}).ok_or_else(||at(Error::InvalidReference,0))?;
    if from==to{return Ok(());}if from==0||to>=track.duration{return Err(at(Error::InvalidValue,0));}
    for (i,s) in track.item_spans.iter().enumerate(){if i!=index{let f=fields(source,*s)?;let t=uint(source,field(&f,b"tick").ok_or_else(||at(Error::InvalidSchema,s.start))?.value).map_err(EditFailure::from)?;if t==to{return Err(at(Error::Duplicate,s.start));}}}
    let count=track.item_spans.len();let mut order=Vec::new();order.try_reserve_exact(count).map_err(|_|at(Error::Limit,track.items.start))?;
    for i in 0..count{if i!=index{let s=track.item_spans[i];let f=fields(source,s)?;let t=uint(source,field(&f,b"tick").ok_or_else(||at(Error::InvalidSchema,s.start))?.value).map_err(EditFailure::from)?;order.push((t,i));}}
    order.push((to,index));order.sort_by_key(|entry|entry.0);
    let mut out=Vec::new();out.try_reserve_exact(source.len().checked_add(10).ok_or_else(||at(Error::Limit,0))?).map_err(|_|at(Error::Limit,0))?;
    append(&mut out,&source[..track.item_spans[0].start])?;
    for (position,(_,i)) in order.iter().enumerate(){let span=track.item_spans[*i];if *i==index{
            let f=fields(source,span)?;let tick_span=field(&f,b"tick").ok_or_else(||at(Error::InvalidSchema,span.start))?.value;
            append(&mut out,&source[span.start..tick_span.start])?;append(&mut out,to.to_string().as_bytes())?;append(&mut out,&source[tick_span.end..span.end])?;
        }else{append(&mut out,&source[span.start..span.end])?;}
        if position+1<count{let left=track.item_spans[position];let right=track.item_spans[position+1];append(&mut out,&source[left.end..right.start])?;}
    }
    append(&mut out,&source[track.item_spans[count-1].end..])?;edit.commit(context,out)
}

pub(super) fn set_loop(edit:&mut TimelineEdit,context:&TimelineContext,mode:LoopMode)->EditResult{
    let source=edit.source();let view=decode(source,context).map_err(EditFailure::from)?;if view.loop_mode()==mode{return Ok(());}let root=fields(source,root_span(source)?)?;let f=field(&root,b"loop").ok_or_else(||at(Error::InvalidSchema,0))?;
    let name=match mode{LoopMode::Once=>b"once".as_slice(),LoopMode::Repeat=>b"loop",LoopMode::PingPong=>b"ping_pong"};let encoded=json_string(name)?;let candidate=splice(source,f.value.start,f.value.end-f.value.start,&encoded)?;edit.commit(context,candidate)
}
pub(super) fn set_onion(edit:&mut TimelineEdit,context:&TimelineContext,before:u32,after:u32,opacity:f64)->EditResult{
    if before>8||after>8||!opacity.is_finite()||!(0.0..=1.0).contains(&opacity){return Err(at(Error::InvalidArgument,0));}
    let source=edit.source();let view=decode(source,context).map_err(EditFailure::from)?;let current=view.onion();if current.0==before&&current.1==after&&current.2==opacity{return Ok(());}let root=fields(source,root_span(source)?)?;let onion=field(&root,b"onion").ok_or_else(||at(Error::InvalidSchema,0))?;let f=fields(source,onion.value)?;
    let reserve=source.len().checked_add(64).ok_or_else(||at(Error::Limit,onion.value.start))?;let mut patches=Vec::new();patches.try_reserve_exact(3).map_err(|_|at(Error::Limit,onion.value.start))?;
    for (key,value) in [(b"before".as_slice(),before.to_string()),(b"after".as_slice(),after.to_string()),(b"opacity".as_slice(),opacity.to_string())]{let s=field(&f,key).ok_or_else(||at(Error::InvalidSchema,onion.value.start))?.value;patches.push((s,value.into_bytes()));}
    patches.sort_by_key(|p|p.0.start);let mut out=Vec::new();out.try_reserve_exact(reserve).map_err(|_|at(Error::Limit,onion.value.start))?;let mut cursor=0;
    for (span,value) in patches{append(&mut out,&source[cursor..span.start])?;append(&mut out,&value)?;cursor=span.end;}append(&mut out,&source[cursor..])?;edit.commit(context,out)
}

use std::sync::Arc;
use std::fmt::Write as _;
use vexel_timeline::{AssetRef, EditFailure, EditLimits, Error, LoopMode, TimelineContext, TimelineEdit, DEFAULT_HISTORY_COMMANDS, DEFAULT_HISTORY_BYTES, MAX_HISTORY_BYTES};

fn context() -> TimelineContext {
    TimelineContext { scene_ids: vec![b"layer".to_vec(), b"shape".to_vec()], assets: vec![
        AssetRef { name:b"cel0".to_vec(), media_type:b"image/svg+xml".to_vec() },
        AssetRef { name:b"cel1".to_vec(), media_type:b"image/svg+xml".to_vec() },
    ] }
}
fn initial() -> String { r#"{ "schema":"vexel.animation","version":1,"ticks_per_second":24,"duration_ticks":24,"fps":{"numerator":24,"denominator":1},"loop":"once","onion":{"before":0,"after":0,"opacity":1},"tracks" : [ ] }"#.to_owned() }
fn fresh() -> TimelineEdit { let src=initial();TimelineEdit::new(src.as_bytes(),&context(),EditLimits::default()).unwrap() }
fn has(haystack:&[u8],needle:&[u8])->bool{haystack.windows(needle.len()).any(|w|w==needle)}

#[test]
fn snapshots_copy_source_and_leases_survive_editor_drop_and_are_send_sync(){
    fn send_sync<T:Send+Sync>(){}send_sync::<vexel_timeline::TimelineSourceLease>();
    let mut input=initial().into_bytes();let ctx=context();let mut edit=TimelineEdit::new(&input,&ctx,EditLimits::default()).unwrap();input.fill(b'x');
    let lease=edit.source_lease();let expected=lease.bytes().to_vec();
    edit.set_loop(&ctx,LoopMode::Repeat).unwrap();drop(edit);
    assert_eq!(lease.bytes(),expected.as_slice());let moved=Arc::new(lease);let worker=std::thread::spawn(move||moved.bytes().to_vec());assert_eq!(worker.join().unwrap(),expected);
}

#[test]
fn leases_survive_history_eviction_without_copying_their_snapshot(){
    let ctx=context();let src=initial();let mut edit=TimelineEdit::new(src.as_bytes(),&ctx,EditLimits{commands:2,bytes:1_000_000}).unwrap();
    let lease=edit.source_lease();let pinned=lease.bytes().as_ptr();
    for mode in [LoopMode::PingPong,LoopMode::Repeat,LoopMode::Once,LoopMode::PingPong,LoopMode::Repeat]{edit.set_loop(&ctx,mode).unwrap();}
    assert_eq!(edit.undo_count(),2);assert_eq!(lease.bytes().as_ptr(),pinned);assert_eq!(lease.bytes(),src.as_bytes());drop(edit);
    assert_eq!(lease.bytes(),src.as_bytes());
}

#[test]
fn drawing_track_cel_edits_keep_json_strings_and_baseline_rules(){
    let ctx=context();let mut e=fresh();e.add_drawing_track(&ctx,b"draw",b"layer",b"cel0",b"Sketch \"A\"").unwrap();
    assert!(has(e.source(),br#""name":"Sketch \"A\""#));assert!(has(e.source(),b"\"tracks\" : ["));
    e.set_cel(&ctx,b"draw",12,b"cel1",b"pose \"B\"\nline").unwrap();assert!(has(e.source(),br#""label":"pose \"B\"\u000aline"#));
    e.set_cel(&ctx,b"draw",12,b"cel0",b"").unwrap();assert!(!has(e.source(),b"label"));
    e.set_cel(&ctx,b"draw",6,b"cel1",b"").unwrap();
    let view=vexel_timeline::decode(e.source(),&ctx).unwrap();assert_eq!(view.item_at(0,1).unwrap().tick,6);
    e.remove_cel(&ctx,b"draw",6).unwrap();assert_eq!(vexel_timeline::decode(e.source(),&ctx).unwrap().track_at(0).unwrap().item_count,2);
    let before=e.source().to_vec();let error=e.remove_cel(&ctx,b"draw",0).unwrap_err();assert_eq!(error.error,Error::Duplicate);assert_eq!(e.source(),before);
}

#[test]
fn splices_preserve_other_tracks_and_surrounding_source_bytes(){
    let source=r#"{"schema":"vexel.animation","version":1,"ticks_per_second":24,"duration_ticks":24,"fps":{"numerator":24,"denominator":1},"loop":"once","onion":{"before":0,"after":0,"opacity":1},"tracks" : [ { "id":"draw", "kind":"drawing", "target":"layer", "visible":true, "cels" : [ { "tick" : 0 , "asset" : "cel0" } ,  {"tick":12,"asset":"cel1","label":"old"}  ] }, { "id":"other", "kind":"drawing", "target":"layer", "visible":true, "cels":[{"tick":0,"asset":"cel0"}], "name":"keep" } ] }"#;
    let ctx=context();let mut e=TimelineEdit::new(source.as_bytes(),&ctx,EditLimits::default()).unwrap();
    e.set_cel(&ctx,b"draw",12,b"cel0",b"replacement").unwrap();
    assert!(has(e.source(),b"\"cels\" : [ { \"tick\" : 0 , \"asset\" : \"cel0\" } ,  "));
    assert!(has(e.source(),b"  ] }, { \"id\":\"other\", \"kind\":\"drawing\", \"target\":\"layer\", \"visible\":true, \"cels\":[{\"tick\":0,\"asset\":\"cel0\"}], \"name\":\"keep\" } ] }"));
    e.set_cel(&ctx,b"draw",6,b"cel1",b"").unwrap();e.remove_cel(&ctx,b"draw",6).unwrap();
    assert!(has(e.source(),b"{ \"tick\" : 0 , \"asset\" : \"cel0\" }"));assert!(has(e.source(),b"\"label\":\"replacement\""));
    let invalid=[0xc0,0x80];let before=e.source().to_vec();assert_eq!(e.set_cel(&ctx,b"draw",6,b"cel1",&invalid).unwrap_err().error,Error::InvalidArgument);assert_eq!(e.source(),before);
}

#[test]
fn rejected_edits_preserve_source_cursor_and_redo(){
    let ctx=context();let mut e=fresh();e.add_drawing_track(&ctx,b"draw",b"layer",b"cel0",b"").unwrap();e.set_cel(&ctx,b"draw",12,b"cel1",b"").unwrap();
    e.undo(&ctx).unwrap();let before=e.source().to_vec();let redo=e.redo_count();let undo=e.undo_count();
    assert_eq!(e.add_drawing_track(&ctx,b"draw",b"layer",b"cel0",b"").unwrap_err().error,Error::Duplicate);
    assert_eq!(e.set_cel(&ctx,b"draw",24,b"cel0",b"").unwrap_err().error,Error::InvalidValue);
    assert_eq!(e.remove_cel(&ctx,b"draw",12).unwrap_err().error,Error::InvalidReference);
    assert_eq!(e.source(),before);assert_eq!(e.undo_count(),undo);assert_eq!(e.redo_count(),redo);
}

#[test]
fn undo_redo_and_branching_restore_exact_sources(){
    let ctx=context();let mut e=fresh();let initial=e.source().to_vec();e.add_drawing_track(&ctx,b"draw",b"layer",b"cel0",b"").unwrap();let track=e.source().to_vec();
    e.set_onion(&ctx,2,4,0.25).unwrap();let onion=e.source().to_vec();assert!(has(&onion,b"\"before\":2,\"after\":4,\"opacity\":0.25"));
    e.undo(&ctx).unwrap();assert_eq!(e.source(),track);e.redo(&ctx).unwrap();assert_eq!(e.source(),onion);
    e.undo(&ctx).unwrap();e.set_loop(&ctx,LoopMode::PingPong).unwrap();assert_eq!(e.redo_count(),0);assert_ne!(e.source(),track);
    e.undo(&ctx).unwrap();assert_eq!(e.source(),track);e.undo(&ctx).unwrap();assert_eq!(e.source(),initial);
}

#[test]
fn history_limits_trim_and_reject_without_partial_commit(){
    assert_eq!(EditLimits::default(),EditLimits{commands:DEFAULT_HISTORY_COMMANDS,bytes:DEFAULT_HISTORY_BYTES});
    assert!(TimelineEdit::new(initial().as_bytes(),&context(),EditLimits{commands:0,bytes:1000}).is_err());
    assert!(TimelineEdit::new(initial().as_bytes(),&context(),EditLimits{commands:1,bytes:MAX_HISTORY_BYTES+1}).is_err());
    let ctx=context();let src=initial();let mut e=TimelineEdit::new(src.as_bytes(),&ctx,EditLimits{commands:1,bytes:1_000_000}).unwrap();
    e.add_drawing_track(&ctx,b"draw",b"layer",b"cel0",b"").unwrap();e.set_cel(&ctx,b"draw",12,b"cel1",b"").unwrap();assert_eq!(e.undo_count(),1);
    e.undo(&ctx).unwrap();assert_eq!(e.redo_count(),1);e.redo(&ctx).unwrap();assert_eq!(e.undo_count(),1);
    let mut tight=TimelineEdit::new(src.as_bytes(),&ctx,EditLimits{commands:4,bytes:src.len()}).unwrap();let before=tight.source().to_vec();
    assert_eq!(tight.add_drawing_track(&ctx,b"draw",b"layer",b"cel0",b"").unwrap_err().error,Error::Limit);assert_eq!(tight.source(),before);
}

#[test]
fn editor_track_limit_is_exact_and_rejection_is_atomic(){
    let ctx=context();let mut tracks=String::new();for i in 0..256{if i>0{tracks.push(',');}write!(&mut tracks,r#"{{"id":"t{i}","kind":"property","target":"shape","visible":true,"property":"opacity","value_type":"scalar","interpolation":"linear","keys":[{{"tick":0,"value":1}}]}}"#).unwrap();}
    let source=format!(r#"{{"schema":"vexel.animation","version":1,"ticks_per_second":24,"duration_ticks":24,"fps":{{"numerator":24,"denominator":1}},"loop":"once","onion":{{"before":0,"after":0,"opacity":1}},"tracks":[{tracks}]}}"#);
    let mut edit=TimelineEdit::new(source.as_bytes(),&ctx,EditLimits::default()).unwrap();let before=edit.source().to_vec();
    assert_eq!(edit.add_drawing_track(&ctx,b"extra",b"layer",b"cel0",b"").unwrap_err().error,Error::Limit);assert_eq!(edit.source(),before);
}

#[test]
fn property_track_keys_and_combined_authoring_preserve_raw_values(){
    let ctx=context();let mut e=fresh();e.add_property_track(&ctx,b"fade",b"shape",b"opacity",b"scalar",b"linear",b"1.00",b"Fade").unwrap();
    assert!(has(e.source(),b"\"value\":1.00"));e.set_property_key(&ctx,b"fade",12,b"0.250").unwrap();assert!(has(e.source(),b"\"value\":0.250"));
    e.set_property_key(&ctx,b"fade",12,b"0.5").unwrap();let view=vexel_timeline::decode(e.source(),&ctx).unwrap();assert_eq!(view.track_at(0).unwrap().item_count,2);
    let mut one=fresh();one.add_property_track_key(&ctx,b"fade",b"shape",b"opacity",b"scalar",b"linear",b"1",12,b"0.25",b"").unwrap();assert_eq!(one.undo_count(),1);one.undo(&ctx).unwrap();assert!(one.source().ends_with(b"[ ] }"));one.redo(&ctx).unwrap();
}

#[test]
fn item_moves_keep_payload_and_reject_baseline_or_collision(){
    let ctx=context();let mut e=fresh();e.add_drawing_track(&ctx,b"draw",b"layer",b"cel0",b"").unwrap();e.set_cel(&ctx,b"draw",6,b"cel1",b"special").unwrap();e.set_cel(&ctx,b"draw",12,b"cel0",b"").unwrap();
    e.move_item(&ctx,b"draw",6,18).unwrap();let v=vexel_timeline::decode(e.source(),&ctx).unwrap();assert_eq!(v.item_at(0,1).unwrap().tick,12);assert_eq!(v.item_at(0,2).unwrap().tick,18);assert!(has(e.source(),b"special"));
    let before=e.source().to_vec();assert_eq!(e.move_item(&ctx,b"draw",18,12).unwrap_err().error,Error::Duplicate);assert_eq!(e.source(),before);
    assert_eq!(e.move_item(&ctx,b"draw",0,1).unwrap_err().error,Error::InvalidValue);assert_eq!(e.source(),before);
    e.move_item(&ctx,b"draw",18,18).unwrap();assert_eq!(e.source(),before);
}

#[test]
fn loop_onion_controls_are_source_preserving_locale_independent_and_undoable(){
    let ctx=context();let mut e=fresh();let before=e.source().to_vec();e.set_loop(&ctx,LoopMode::Once).unwrap();assert_eq!(e.source(),before);
    e.set_loop(&ctx,LoopMode::PingPong).unwrap();assert!(has(e.source(),b"\"loop\":\"ping_pong\""));assert!(has(e.source(),b"\"tracks\" : [ ]"));
    let loop_source=e.source().to_vec();e.set_onion(&ctx,1,3,0.25).unwrap();assert!(has(e.source(),b"\"before\":1,\"after\":3,\"opacity\":0.25"));
    e.undo(&ctx).unwrap();assert_eq!(e.source(),loop_source);e.redo(&ctx).unwrap();
    let current=e.source().to_vec();assert_eq!(e.set_onion(&ctx,9,0,0.2).unwrap_err().error,Error::InvalidArgument);assert_eq!(e.set_onion(&ctx,1,1,f64::NAN).unwrap_err().error,Error::InvalidArgument);assert_eq!(e.source(),current);
}

#[test]
fn context_is_per_operation_and_failed_redo_keeps_cursor(){
    let ctx=context();let mut e=fresh();e.add_drawing_track(&ctx,b"draw",b"layer",b"cel0",b"").unwrap();
    e.set_cel(&ctx,b"draw",12,b"cel1",b"").unwrap();e.undo(&ctx).unwrap();let before=e.source().to_vec();let empty=TimelineContext::default();
    assert!(e.redo(&empty).is_err());assert_eq!(e.source(),before);assert_eq!(e.redo_count(),1);e.redo(&ctx).unwrap();
}

#[test]
fn edit_errors_keep_failure_offsets_and_source(){
    let ctx=context();let mut e=fresh();let before=e.source().to_vec();let error:EditFailure=e.set_cel(&ctx,b"missing",2,b"cel0",b"").unwrap_err();
    assert_eq!(error.error,Error::InvalidReference);assert_eq!(error.offset,0);assert_eq!(e.source(),before);
    assert_eq!(e.add_drawing_track(&ctx,b"bad/id",b"layer",b"cel0",b"").unwrap_err(),EditFailure{error:Error::InvalidValue,offset:3});
}

